// Group equivalent compositions; choose the lowest-hull record for each reported layer count.
function reducedComposition(formula){
 const atoms=new Map();for(const match of formula.matchAll(/([A-Z][a-z]?)(\d*)/g))atoms.set(match[1],(atoms.get(match[1])||0)+Number(match[2]||1));
 const gcd=(a,b)=>b?gcd(b,a%b):a;const factor=[...atoms.values()].reduce(gcd);
 const entries=[...atoms].map(([el,n])=>[el,n/factor]);
 return {name:entries.map(([el,n])=>el+(n===1?'':n)).join(''),key:entries.sort(([a],[b])=>a.localeCompare(b)).map(([el,n])=>el+n).join('|')};
}
const compositionGroups=new Map();
for(const record of C2DB_RECORDS){
 const composition=reducedComposition(record.formula),layers=record.origin==='Americo23'?2:1;
 if(!compositionGroups.has(composition.key))compositionGroups.set(composition.key,{name:composition.name,records:new Map()});
 const group=compositionGroups.get(composition.key),previous=group.records.get(layers);
 if(!previous||record.ehull<previous.ehull||(record.ehull===previous.ehull&&record.uid.localeCompare(previous.uid)<0))group.records.set(layers,record);
}
const semiconductors=[...compositionGroups.values()].map((group,i)=>{
 const rows=[...group.records].sort(([a],[b])=>a-b).map(([layers,record])=>({layers,record,chi:-record.cbm,eg:Math.round((record.cbm-record.vbm)*1000)/1000,source:'https://c2db.fysik.dtu.dk/material/'+encodeURIComponent(record.uid)}));
 return {id:'s'+i,name:group.name,zh:'',color:'#72bdc8',source:rows[0].source,method:'PBE',record:rows[0].record,note:'C2DB · Representative PBE calculation',rows};
});
